import React, { useState } from "react";
import Login from "./Login";
import Signup from "./Signup";
import "./App.css";

function App() {

  const [page, setPage] = useState("login");

  return (

    <div className="main">

      <h1 className="title">📚 LMS Portal</h1>

      {page === "login" ? (
        <>
          <Login />
          <p>
            New user? 
            <button className="linkBtn" onClick={() => setPage("signup")}>
              Register Here
            </button>
          </p>
        </>
      ) : (
        <>
          <Signup />
          <p>
            Already have account? 
            <button className="linkBtn" onClick={() => setPage("login")}>
              Login
            </button>
          </p>
        </>
      )}

    </div>

  );
}

export default App;
